import { useState, useRef, useEffect } from "react";
import { weddingData } from "@/data/weddingData";

const LEFT_BRANCH = "data:image/png;base64,";
const RIGHT_BRANCH = "data:image/png;base64,";
function EnvelopeLogo() {
  return (
    <div
      style={{
        position:"relative",
        display:"flex",
        alignItems:"center",
        justifyContent:"center",
        width:"100%",
        maxWidth:640,
        minHeight:"clamp(132px,24vw,196px)",
      }}
    >
      {/* Left eucalyptus branch */}
      <img
        src={LEFT_BRANCH}
        alt=""
        aria-hidden="true"
        style={{
          position:"absolute",
          left: "clamp(4px,1.5vw,18px)",
          top: "50%",
          transform: "translateY(-50%)",
          height: "clamp(122px,24vw,190px)",
          width: "auto",
          objectFit: "contain",
          objectPosition: "left center",
          pointerEvents: "none",
          userSelect: "none",
        }}
      />
      {/* Right eucalyptus branch */}
      <img
        src={RIGHT_BRANCH}
        alt=""
        aria-hidden="true"
        style={{
          position:"absolute",
          right: "clamp(4px,1.5vw,18px)",
          top: "50%",
          transform: "translateY(-50%)",
          height: "clamp(122px,24vw,190px)",
          width: "auto",
          objectFit: "contain",
          objectPosition: "right center",
          pointerEvents: "none",
          userSelect: "none",
        }}
      />
      {/* Centre text */}
      <div
        style={{
          textAlign:"center",
          fontFamily:"'Cormorant Garamond',Georgia,serif",
          color:"var(--template-primary-dark)",
          padding:"0 clamp(44px,12vw,146px)",
          zIndex:1,
          display:"flex",
          flexDirection:"column",
          alignItems:"center",
          justifyContent:"center",
          gap:"clamp(6px,1.5vw,10px)",
          transform:"translateY(8px)",
        }}
      >
        <h1 style={{
          fontSize:"clamp(18px,6.4vw,50px)",
          fontWeight:400,
          letterSpacing:"clamp(0.02em,0.22vw,0.12em)",
          margin:0,
          lineHeight:1.05,
          whiteSpace:"nowrap",
          maxWidth:"100%",
        }}>
          <span data-editor-key="couple.partner1">{weddingData.couple.partner1}</span>
          {" & "}
          <span data-editor-key="couple.partner2">{weddingData.couple.partner2}</span>
        </h1>
        <p style={{
          fontSize:"clamp(8px,2.6vw,14px)",
          letterSpacing:"clamp(0.12em,0.9vw,0.28em)",
          textTransform:"uppercase",
          color:"var(--template-primary)",
          margin:0,
          lineHeight:1.2,
          fontFamily:"'Montserrat',sans-serif",
          fontWeight:300,
        }} data-editor-key="event.dateLabel">{weddingData.event.dateLabel}</p>
      </div>
    </div>
  );
}

function WebsiteLogo({ big }: { big?: boolean }) {
  return (
    <div
      style={{
        alignItems: "center",
        display: "flex",
        height: "100%",
        justifyContent: "center",
        textAlign: "center",
        width: "100%",
        transform: big ? "scale(1.15)" : "scale(0.82)",
      }}
    >
      <EnvelopeLogo />
    </div>
  );
}

type EnvelopeIntroProps = {
  onComplete?: () => void;
};

type IntroStage = "closed" | "opening" | "lifting" | "logo" | "leaving";

export default function EnvelopeIntro({ onComplete }: EnvelopeIntroProps) {
  const [stage, setStage] = useState<IntroStage>("closed");
  const [flapBehind, setFlapBehind] = useState(false);
  const [showHint, setShowHint] = useState(false);
  const timers = useRef<number[]>([]);
  const completed = useRef(false);

  const at = (ms: number, fn: () => void) => {
    const id = window.setTimeout(fn, ms);
    timers.current.push(id);
  };

  useEffect(() => {
    return () => timers.current.forEach(window.clearTimeout);
  }, []);

  useEffect(() => {
    const fontId = "wedding-intro-fonts";
    if (document.getElementById(fontId)) return;

    const link = document.createElement("link");
    link.id = fontId;
    link.rel = "stylesheet";
    link.href = "https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@300;400;500;600&family=Montserrat:wght@200;300;400;500&display=swap";
    document.head.appendChild(link);
  }, []);

  useEffect(() => {
    if (stage !== "closed") return;

    const hintIn = window.setTimeout(() => setShowHint(true), 6500);
    const hintOut = window.setTimeout(() => setShowHint(false), 11000);
    timers.current.push(hintIn, hintOut);

    return () => {
      clearTimeout(hintIn);
      clearTimeout(hintOut);
    };
  }, [stage]);

  const completeIntro = () => {
    if (completed.current) return;
    completed.current = true;
    onComplete?.();
  };

  const handleOpen = () => {
    if (stage !== "closed") return;

    setShowHint(false);
    setStage("opening");
    at(850, () => {
      setFlapBehind(true);
      setStage("lifting");
    });
    at(1380, () => setStage("logo"));
    at(2600, () => {
      setStage("leaving");
      completeIntro();
    });
  };

  const flapOpen = stage !== "closed";
  const lifted = ["lifting", "logo", "leaving"].includes(stage);
  const logoPhase = ["logo", "leaving"].includes(stage);
  const leaving = stage === "leaving";

  return (
    <div style={{ fontFamily: "'Cormorant Garamond', Georgia, serif", minHeight: "100vh", background: "transparent" }}>
      <style>{`
        @keyframes envIn {
          from { opacity:0; transform:translateY(20px) scale(0.97); }
          to { opacity:1; transform:translateY(0) scale(1); }
        }
        @keyframes pulse {
          0%,100% { opacity:.5; transform:translateX(-50%) scale(1); }
          50% { opacity:.78; transform:translateX(-50%) scale(1.035); }
        }
        @keyframes fingerTap {
          0%, 100% { transform: translate(-50%, -50%) scale(1); opacity:.45; }
          45% { transform: translate(-50%, -42%) scale(1.08); opacity:.82; }
        }
        .env-in { animation: envIn 900ms cubic-bezier(.22,1,.36,1) both; }
        .soft-glow { animation: pulse 5.5s ease-in-out infinite; }
        .seal-btn:hover { background:var(--template-text) !important; transform:translate(-50%,-50%) scale(1.045) !important; }
      `}</style>

      <div
        style={{
          position: "fixed",
          inset: 0,
          zIndex: 140,
          background: "linear-gradient(180deg, #ffffff 0%, var(--template-surface) 100%)",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          padding: "20px",
          transition: "opacity 850ms ease-out, filter 850ms ease-out",
          opacity: leaving ? 0 : 1,
          filter: leaving ? "blur(8px)" : "blur(0)",
          pointerEvents: leaving ? "none" : "auto",
        }}
      >
        <div style={{ position: "absolute", inset: 16, border: "1px solid color-mix(in srgb, var(--template-soft) 42%, transparent)", pointerEvents: "none" }} />
        <div style={{ position: "absolute", inset: 28, border: "1px solid color-mix(in srgb, var(--template-soft) 22%, transparent)", pointerEvents: "none" }} />
        <div
          aria-label="Nupia"
          style={{
            position: "absolute",
            top: "clamp(34px, 6vw, 62px)",
            left: "clamp(38px, 7vw, 96px)",
            zIndex: 8,
            display: "flex",
            alignItems: "center",
            gap: 9,
            color: "var(--template-primary-dark)",
            fontFamily: "'Montserrat', sans-serif",
            fontSize: 9,
            fontWeight: 500,
            letterSpacing: "0.24em",
          }}
        >
          <img src="/images/nupia-mark.png" alt="" style={{ width: 19, height: 28, objectFit: "contain", opacity: 0.72 }} />
          <span>NUPIA</span>
        </div>

        <div style={{ width: "100%", maxWidth: 640, display: "flex", flexDirection: "column", alignItems: "center" }}>
          <div
            style={{
              overflow: "hidden",
              maxHeight: stage === "closed" ? 300 : 0,
              opacity: stage === "closed" ? 1 : 0,
              transform: stage === "closed" ? "translateY(0)" : "translateY(-18px)",
              transition: "max-height 620ms ease-out, opacity 480ms ease-out, transform 480ms ease-out",
              marginBottom: -10,
              width: "100%",
              display: "flex",
              justifyContent: "center",
            }}
          >
            <EnvelopeLogo />
          </div>

          <div
            className="env-in"
            style={{
              position: "relative",
              width: "100%",
              maxWidth: 500,
              height: 290,
              perspective: "1500px",
              isolation: "isolate",
            }}
          >
            <div
              className="soft-glow"
              style={{
                position: "absolute",
                left: "50%",
                top: 58,
                width: 500,
                height: 210,
                borderRadius: "50%",
                background: "color-mix(in srgb, var(--template-primary) 7%, transparent)",
                filter: "blur(42px)",
                pointerEvents: "none",
              }}
            />
            <div
              style={{
                position: "absolute",
                bottom: -4,
                left: "8%",
                right: "8%",
                height: 24,
                background: "color-mix(in srgb, var(--template-primary-dark) 9%, transparent)",
                borderRadius: "50%",
                filter: "blur(16px)",
                pointerEvents: "none",
              }}
            />

            <div style={{ position: "absolute", left: 0, top: 30, height: 220, width: "100%" }}>
              <div style={{ position: "absolute", inset: 0, background: "var(--template-surface)", boxShadow: "0 28px 60px color-mix(in srgb, var(--template-primary-dark) 12%, transparent)", zIndex: 1 }} />

              <div
                style={{
                  position: "absolute",
                  left: "50%",
                  transform: "translateX(-50%)",
                  overflow: "hidden",
                  background: "#fff",
                  border: "1px solid var(--template-border)",
                  boxShadow: logoPhase
                    ? "0 28px 90px color-mix(in srgb, var(--template-primary-dark) 14%, transparent)"
                    : "0 12px 30px color-mix(in srgb, var(--template-primary-dark) 10%, transparent)",
                  width: logoPhase ? "min(92vw, 900px)" : "78%",
                  height: logoPhase ? "min(54vh, 420px)" : "130px",
                  top: logoPhase ? "-58px" : lifted ? "-18px" : "44px",
                  zIndex: logoPhase ? 30 : 2,
                  borderRadius: logoPhase ? "28px" : "0px",
                  transitionProperty: "top,width,height,border-radius,box-shadow",
                  transitionDuration: logoPhase ? "1050ms" : "640ms",
                  transitionTimingFunction: logoPhase ? "cubic-bezier(.22,1,.36,1)" : "cubic-bezier(.34,1.2,.64,1)",
                }}
              >
                <div
                  style={{
                    height: "100%",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    padding: logoPhase ? "28px" : "16px",
                  }}
                >
                  <WebsiteLogo big={logoPhase} />
                </div>
              </div>

              <div style={{ position: "absolute", left: 0, top: 0, height: 116, width: "100%", zIndex: flapBehind ? 0 : 9, transformStyle: "preserve-3d" }}>
                {[
                  { bg: "var(--template-soft)", tz: 1 },
                  { bg: "var(--template-surface)", tz: 0 },
                ].map(({ bg, tz }) => (
                  <div
                    key={tz}
                    style={{
                      position: "absolute",
                      inset: 0,
                      background: bg,
                      clipPath: "polygon(0 0,100% 0,50% 100%)",
                      transformOrigin: "50% 0%",
                      transformStyle: "preserve-3d",
                      backfaceVisibility: "visible",
                      transform: flapOpen ? `rotateX(180deg) translateZ(${tz}px)` : `rotateX(0deg) translateZ(${tz}px)`,
                      transition: "transform 920ms cubic-bezier(.33,1,.68,1)",
                    }}
                  />
                ))}
              </div>

              <div style={{ position: "absolute", inset: 0, overflow: "hidden", pointerEvents: "none", zIndex: 4 }}>
                <div style={{ position: "absolute", inset: "0 50% 0 0", background: "var(--template-surface)", clipPath: "polygon(0 0,100% 52%,0 100%)" }} />
                <div style={{ position: "absolute", inset: "0 0 0 50%", background: "var(--template-soft)", clipPath: "polygon(100% 0,0 52%,100% 100%)" }} />
              </div>
              <div style={{ position: "absolute", inset: 0, overflow: "hidden", pointerEvents: "none", zIndex: 5 }}>
                <div style={{ position: "absolute", inset: 0, background: "var(--template-surface)", clipPath: "polygon(0 100%,50% 30%,100% 100%)" }} />
              </div>
              <div style={{ position: "absolute", left: "9%", right: "9%", top: 238, height: 1, background: "var(--template-border)", zIndex: 6, pointerEvents: "none" }} />

              {!logoPhase && (
                <button
                  className="seal-btn"
                  onClick={handleOpen}
                  disabled={stage !== "closed"}
                  aria-label="Abrir invitación"
                  style={{
                    position: "absolute",
                    left: "50%",
                    top: "50%",
                    transform: "translate(-50%,-50%)",
                    zIndex: 20,
                    width: 94,
                    height: 94,
                    borderRadius: "50%",
                    background: "var(--template-primary)",
                    border: "1px solid var(--template-text)",
                    boxShadow: "0 10px 22px color-mix(in srgb, var(--template-primary-dark) 18%, transparent)",
                    cursor: stage === "closed" ? "pointer" : "default",
                    outline: "none",
                    transition: "transform 300ms, background 300ms",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                  }}
                >
                  <div style={{ position: "absolute", inset: 7, borderRadius: "50%", border: "1px solid color-mix(in srgb, var(--template-soft) 75%, white)" }} />
                  <span
                    style={{
                      fontFamily: "'Cormorant Garamond', serif",
                      fontSize: 26,
                      fontWeight: 600,
                      color: "#E8F5EA",
                      letterSpacing: "0.04em",
                      display: "flex",
                      alignItems: "center",
                      gap: 5,
                      position: "relative",
                      zIndex: 1,
                    }}
                  >
                    <span>{weddingData.couple.partner1.charAt(0) || "N"}</span>
                    <span style={{ fontSize: 17, opacity: 0.85, fontWeight: 400 }}>&amp;</span>
                    <span>{weddingData.couple.partner2.charAt(0) || "N"}</span>
                  </span>
                </button>
              )}

              {showHint && stage === "closed" && (
                <div
                  style={{
                    position: "absolute",
                    left: "50%",
                    top: "calc(50% + 28px)",
                    zIndex: 30,
                    pointerEvents: "none",
                    fontSize: 32,
                    opacity: 0.7,
                    userSelect: "none",
                    animation: "fingerTap 1.35s ease-in-out infinite",
                  }}
                >
                  👆
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
